shareButton?.addEventListener('click', async () => {
  const dict = translations[currentLang] || translations.en;
  const shareData = { title: document.title, text: dict.heroTitleMobile, url: `${location.origin}${location.pathname}` };
  try {
    if (navigator.share) {
      await navigator.share(shareData);
      return;
    }
    await copyPageUrl(shareData.url);
    const original = shareButton.textContent;
    shareButton.textContent = dict.shareCopied;
    window.setTimeout(() => { shareButton.textContent = original; }, 1800);
  } catch (error) {
    if (error?.name !== 'AbortError') console.error('Page share failed.', error);
  }
});

async function copyPageUrl(url) {
  if (navigator.clipboard?.writeText) return navigator.clipboard.writeText(url);
  const input = document.createElement('textarea');
  input.value = url; input.setAttribute('readonly', ''); input.style.position = 'fixed'; input.style.opacity = '0';
  document.body.append(input); input.select(); document.execCommand('copy'); input.remove();
}

